<script lang="ts">
    import { resolveProp, resolveStyles } from '../../helpers/resolve.js';
    import { type ComponentProps } from 'svelte';
    import type { ScaledDataRecord, UsedScales } from '../../types/index.js';
    import type Text from '../Text.svelte';
    import { CSS_VAR } from '../../constants.js';
    import { maybeFromPixel, maybeFromRem } from '../../helpers/getBaseStyles.js';
    import { usePlot } from '../../hooks/usePlot.svelte.js';

    const LINE_ANCHOR = {
        bottom: 'auto',
        middle: 'central',
        top: 'hanging'
    } as const;

    const plot = usePlot();

    let {
        textLines,
        d,
        args,
        usedScales
    }: {
        textLines: string[];
        d: ScaledDataRecord;
        args: ComponentProps<typeof Text>;
        usedScales: UsedScales;
    } = $props();

    const title = $derived(resolveProp(args.title, d.datum, ''));
    const frameAnchor = $derived(resolveProp(args.frameAnchor, d.datum));
    const isLeft = $derived(
        frameAnchor === 'left' || frameAnchor === 'top-left' || frameAnchor === 'bottom-left'
    );
    const isRight = $derived(
        frameAnchor === 'right' || frameAnchor === 'top-right' || frameAnchor === 'bottom-right'
    );
    const isTop = $derived(
        frameAnchor === 'top' || frameAnchor === 'top-left' || frameAnchor === 'top-right'
    );
    const isBottom = $derived(
        frameAnchor === 'bottom' || frameAnchor === 'bottom-left' || frameAnchor === 'bottom-right'
    );
    const lineAnchor = $derived(
        resolveProp(
            args.lineAnchor,
            d.datum,
            args.y != null ? 'middle' : isTop ? 'top' : isBottom ? 'bottom' : 'middle'
        ) ?? 'middle'
    );
    const textClassName = $derived(resolveProp(args.textClass, d.datum, null));
    const [x, y] = $derived(
        args.x != null && args.y != null
            ? [d.x, d.y]
            : [
                  args.x != null
                      ? d.x
                      : (isLeft
                            ? plot.options.marginLeft
                            : isRight
                              ? plot.options.marginLeft + plot.facetWidth
                              : plot.options.marginLeft + plot.facetWidth * 0.5) + (d.dx ?? 0),
                  args.y != null
                      ? d.y
                      : (isTop
                            ? plot.options.marginTop
                            : isBottom
                              ? plot.options.marginTop + plot.facetHeight
                              : plot.options.marginTop + plot.facetHeight * 0.5) + (d.dy ?? 0)
              ]
    );

    const [style, styleClass] = $derived(
        resolveStyles(
            plot,
            { ...d, __tspanIndex: 0 } as any,
            {
                fontSize: 12,
                fontWeight: 500,
                strokeWidth: 1.6,
                textAnchor: isLeft ? 'start' : isRight ? 'end' : 'middle',
                ...args
            },
            'fill',
            usedScales
        )
    );

    const fontSize = $derived(
        textLines.length > 1 ? (resolveProp(args.fontSize, d.datum) ?? 12) : 0
    );
    let textElement: SVGTextElement | null = $state(null);

    const rootFontSize = $derived(
        textElement != null && textLines.length > 1
            ? maybeFromPixel(
                  getComputedStyle(
                      (textElement as unknown as SVGTextElement).ownerDocument.documentElement
                  ).fontSize
              )
            : 14
    );

    const computedFontSize = $derived(
        textElement &&
            textLines.length > 1 &&
            typeof fontSize === 'string' &&
            CSS_VAR.test(fontSize)
            ? maybeFromRem(
                  maybeFromPixel(
                      getComputedStyle(textElement).getPropertyValue(
                          `--${String(fontSize).match(CSS_VAR)![1]}`
                      )
                  ),
                  rootFontSize as number
              )
            : fontSize
    );

    const lineHeight = $derived(
        textLines.length > 1 ? (resolveProp(args.lineHeight, d.datum) ?? 1.2) : 0
    );

    const rotate = $derived(Number(resolveProp(args.rotate, d.datum, 0) ?? 0));
</script>

{#if textLines.length > 1}
    <!-- multiline text-->
    <text
        bind:this={textElement}
        class={[textClassName]}
        dominant-baseline={LINE_ANCHOR[lineAnchor]}
        transform="translate({Math.round(x ?? 0)},{Math.round(
            (y ?? 0) -
                (lineAnchor === 'bottom'
                    ? textLines.length - 1
                    : lineAnchor === 'middle'
                      ? (textLines.length - 1) * 0.5
                      : 0) *
                    (computedFontSize as number) *
                    lineHeight
        )}) rotate({rotate})"
        >{#each textLines as line, l (l)}<tspan
                x="0"
                dy={l ? (computedFontSize as number) * lineHeight : 0}
                class={styleClass}
                {style}>{line}</tspan
            >{/each}{#if title}<title>{title}</title>{/if}</text>
{:else}
    <!-- singleline text-->
    <text
        class={[textClassName, styleClass]}
        dominant-baseline={LINE_ANCHOR[lineAnchor]}
        transform="translate({Math.round(x ?? 0)},{Math.round(y ?? 0)}) rotate({rotate})"
        {style}
        >{textLines[0]}{#if title}<title>{title}</title>{/if}</text>
{/if}

<style>
    text {
        paint-order: stroke fill;
    }
</style>
