<script lang="ts">
    // this component only takes care of rendering the x axis so we can re-use it
    // for the facet labels
    import { getContext, untrack } from 'svelte';
    import removeIdenticalLines from '../../helpers/removeIdenticalLines.js';
    import type {
        AutoMarginStores,
        ConstantAccessor,
        PlotState,
        PlotScaleFunction,
        RawValue,
        ScaledDataRecord,
        ScaleType
    } from '../../types/index.js';
    import type { AxisTickDatum, AxisXTick, BaseAxisXOptions } from '../../types/axes.js';
    import { resolveProp, resolveStyles } from '../../helpers/resolve.js';
    import { max } from 'd3-array';
    import { randomId, testFilter } from '../../helpers/index.js';
    import { INDEX } from '../../constants.js';
    import { RAW_VALUE } from '../../transforms/recordize.js';
    import wordwrap from '../../helpers/wordwrap.js';
    type AxisDatum = AxisTickDatum<typeof RAW_VALUE, typeof INDEX>;
    type AxisTick = AxisXTick<AxisDatum>;

    type BaseAxisXProps = {
        scaleFn: PlotScaleFunction;
        scaleType: ScaleType;
        ticks: RawValue[];
        tickFormat: (d: RawValue, i: number, ticks: RawValue[]) => string | string[];
        anchor?: 'top' | 'bottom';
        tickSize?: number;
        tickPadding?: number;
        tickFontSize?: ConstantAccessor<number>;
        tickClass?: ConstantAccessor<string>;
        marginTop: number;
        height: number;
        title: string | null;
        options: BaseAxisXOptions;
        text?: boolean | null;
        plot: PlotState;
        class: string | undefined;
    };

    let {
        scaleFn,
        scaleType,
        ticks,
        tickFormat,
        anchor = 'bottom',
        tickSize = 6,
        tickPadding = 3,
        tickFontSize = 11,
        tickClass = null,
        marginTop,
        height,
        options,
        plot,
        title = null,
        class: className = 'axis-x',
        text = true
    }: BaseAxisXProps = $props();

    const isBandScale = $derived(scaleType === 'band');
    const bandWidth = $derived(isBandScale ? scaleFn.bandwidth() : 0);

    function splitTick(tick: string | string[]) {
        return Array.isArray(tick)
            ? tick
            : typeof tick === 'string' && isBandScale && options.wordwrap !== false
              ? wordwrap(tick, {
                    maxLineWidth: bandWidth * 0.9,
                    minCharactersPerLine: 4,
                    fontSize: Number(resolveProp(tickFontSize, null, 11) ?? 11),
                    monospace: false
                })
              : [tick];
    }

    let tickRotate = $derived(plot.options.x.tickRotate || 0);

    let tickY = $derived(anchor === 'bottom' ? marginTop + height : marginTop);

    let isQuantitative = $derived(scaleType !== 'point' && scaleType !== 'band');

    // generate id used for registering margins
    const id = randomId();

    const { autoMarginTop, autoMarginBottom, autoMarginLeft, autoMarginRight } =
        getContext<AutoMarginStores>('svelteplot/autoMargins');

    let tickTextElements = $state([] as (SVGTextElement | undefined)[]);
    const toScaledDatum = (tick: AxisTick) => ({ datum: tick }) as unknown as ScaledDataRecord;

    const positionedTicks = $derived.by(() => {
        let tickObjects = removeIdenticalLines(
            ticks.map((tick, i) => {
                const datum: AxisDatum = { [RAW_VALUE]: tick, [INDEX]: i };
                return {
                    ...datum,
                    hidden: false,
                    dx: Number(resolveProp(options.dx, datum, 0) ?? 0),
                    dy: Number(resolveProp(options.dy, datum, 0) ?? 0),
                    x: scaleFn(tick) + (isBandScale ? scaleFn.bandwidth() * 0.5 : 0),
                    text: splitTick(tickFormat(tick, i, ticks)),
                    element: null as SVGTextElement | null
                };
            })
        ) as AxisTick[];
        const T = tickObjects.length;
        if (text) {
            for (let i = 0; i < T; i++) {
                let j = i;
                // find the preceding tick that was not hidden
                do {
                    j--;
                } while (j >= 0 && tickObjects[j].hidden);
                if (j >= 0) {
                    const tickLabelSpace = Math.abs(tickObjects[i].x - tickObjects[j].x);
                    tickObjects[i].hidden = tickLabelSpace < 15;
                }
            }
        }
        return tickObjects;
    });

    $effect(() => {
        // just add some minimal horizontal margins for axis ticks
        untrack(() => $autoMarginLeft);
        untrack(() => $autoMarginRight);
        $autoMarginLeft.set(id, 5);
        $autoMarginRight.set(id, 10);
    });

    $effect(() => {
        untrack(() => [$autoMarginTop, $autoMarginBottom]);
        if (!text) return;
        const outsideTextAnchor = anchor === 'top' ? 'end' : 'start';
        // measure tick label heights
        const maxLabelHeight =
            Math.ceil(
                max(
                    positionedTicks.map((tick, i) => {
                        if (
                            resolveProp(options.anchor, tick, outsideTextAnchor) !==
                            outsideTextAnchor
                        )
                            return 0;
                        if (tick.hidden || !testFilter(tick, options)) return 0;
                        if (tickTextElements[i])
                            return tickTextElements[i].getBoundingClientRect().height;
                        return 0;
                    }) as number[]
                ) ?? 0
            ) +
            Math.max(0, tickPadding + tickSize) +
            (title ? 15 : 0);

        if (!isNaN(maxLabelHeight)) {
            if (anchor === 'top' && $autoMarginTop.get(id) !== maxLabelHeight) {
                $autoMarginTop.set(id, maxLabelHeight);
            } else if (anchor === 'bottom' && $autoMarginBottom.get(id) !== maxLabelHeight) {
                $autoMarginBottom.set(id, maxLabelHeight);
            }
        }
    });

    $effect(() => {
        // clear margins on destroy
        return () => {
            if ($autoMarginBottom.has(id)) $autoMarginBottom.delete(id);
            if ($autoMarginTop.has(id)) $autoMarginTop.delete(id);
            if ($autoMarginLeft.has(id)) $autoMarginLeft.delete(id);
            if ($autoMarginRight.has(id)) $autoMarginRight.delete(id);
        };
    });
</script>

<g class={className}>
    {#each positionedTicks as tick, t (tick[RAW_VALUE])}
        {#if testFilter(tick, options) && !tick.hidden}
            {@const tickClass_ = resolveProp(tickClass, tick)}
            {@const tickFontSize_ = Number(resolveProp(tickFontSize, tick, 10) ?? 10)}
            <g
                class="tick {tickClass_ || ''}"
                transform="translate({tick.x + tick.dx}, {tickY + tick.dy})"
                text-anchor={tickRotate < 0 ? 'end' : tickRotate > 0 ? 'start' : 'middle'}>
                {#if tickSize}
                    {@const [tickLineStyle, tickLineClass] = resolveStyles(
                        plot,
                        toScaledDatum(tick),
                        options,
                        'stroke',
                        { x: true } as any,
                        true
                    )}
                    <line
                        style={tickLineStyle}
                        class={tickLineClass}
                        y2={anchor === 'bottom' ? tickSize : -tickSize} />
                {/if}

                {#if text}
                    {@const textLines = tick.text}
                    {@const prevTextLines = t > 0 ? positionedTicks[t - 1].text : null}

                    {@const moveDown =
                        (tickSize + tickPadding + (tickRotate !== 0 ? tickFontSize_ * 0.35 : 0)) *
                        (anchor === 'bottom' ? 1 : -1)}
                    {@const tickBaseline =
                        tickRotate !== 0 ? 'central' : anchor === 'bottom' ? 'hanging' : 'auto'}
                    {@const [textStyle, textClass] = resolveStyles(
                        plot,
                        toScaledDatum(tick),
                        {
                            fontVariant: isQuantitative ? 'tabular-nums' : 'normal',
                            ...options,
                            textAnchor:
                                options.textAnchor === 'auto'
                                    ? // automatically adjust text anchor based on rotation
                                      tickRotate < 0
                                        ? 'end'
                                        : tickRotate > 0
                                          ? 'start'
                                          : 'middle'
                                    : options.textAnchor,
                            fontSize: tickFontSize_,
                            stroke: null
                        },
                        'fill',
                        { x: true } as any,
                        true
                    )}
                    <text
                        bind:this={tickTextElements[t]}
                        transform="translate(0, {moveDown}) rotate({tickRotate})"
                        style={textStyle}
                        class={textClass}
                        x={0}
                        y={0}
                        dominant-baseline={tickBaseline}>
                        {#if ticks.length > 0 || t === 0 || t === ticks.length - 1}
                            {#if textLines.length === 1}
                                {textLines[0]}
                            {:else}
                                {#each textLines as line, i (i)}
                                    <tspan x="0" dy={i ? 12 : 0} dominant-baseline={tickBaseline}
                                        >{!prevTextLines ||
                                        prevTextLines[i] !== line ||
                                        options.removeDuplicateTicks === false
                                            ? line
                                            : ''}</tspan>
                                {/each}
                            {/if}
                        {/if}
                    </text>
                {/if}
            </g>
        {/if}
    {/each}
</g>

<style>
    line {
        stroke: currentColor;
    }
    text {
        opacity: 0.8;
        fill: currentColor;
    }
</style>
