<!--
    @component
    The waffleX mark lets you create waffle charts by filling a rectangular area with small squares representing data values.
-->
<script lang="ts" generics="Datum extends DataRecord">
    import type {
        DataRecord,
        BaseMarkProps,
        ChannelAccessor,
        LinkableMarkProps,
        BorderRadius
    } from '../types/index.js';
    import { wafflePolygon, type WaffleOptions } from './helpers/waffle.js';
    import { getPlotDefaults } from '../hooks/plotDefaults.js';
    import { intervalX, recordizeX, sort, stackX } from '../transforms/index.js';
    import type { StackOptions } from '../transforms/stack.js';
    import Mark from '../Mark.svelte';
    import { resolveProp, resolveStyles } from '../helpers/resolve.js';
    import { roundedRect } from '../helpers/roundedRect.js';
    import { usePlot } from '../hooks/usePlot.svelte.js';

    interface WaffleXMarkProps
        extends BaseMarkProps<Datum>, LinkableMarkProps<Datum>, WaffleOptions<Datum> {
        /** the input data array */
        data?: Datum[];
        /**
         * the horizontal position channel; bound to a quantitative scale
         */
        x?: ChannelAccessor<Datum>;
        /**
         * the starting horizontal position; bound to a quantitative scale
         */
        x1?: ChannelAccessor<Datum>;
        /**
         * the ending horizontal position; bound to a quantitative scale
         */
        x2?: ChannelAccessor<Datum>;
        /**
         * the vertical position channel; bound to a band scale
         */
        y?: ChannelAccessor<Datum>;
        /** stacking options for combining multiple series */
        stack?: StackOptions;
    }

    const DEFAULTS = {
        fill: 'currentColor',
        ...getPlotDefaults().waffle,
        ...getPlotDefaults().waffleX
    };

    let markProps: WaffleXMarkProps = $props();

    const {
        data = [{} as Datum],
        class: className = '',
        stack,
        symbol,
        unit,
        ...options
    }: WaffleXMarkProps = $derived({ ...DEFAULTS, ...markProps });

    const plot = usePlot();

    const args = $derived(
        stackX(
            intervalX(
                // by default, sort by y channel (the ordinal labels)
                sort(recordizeX({ data, ...options }))
            ),
            stack
        )
    );
</script>

<Mark
    type="waffleX"
    requiredScales={{ y: ['band'] }}
    channels={['x1', 'x2', 'y', 'fill', 'stroke', 'opacity', 'fillOpacity', 'strokeOpacity']}
    {...args}>
    {#snippet children({ usedScales, scaledData })}
        {@const wafflePoly = wafflePolygon('x', args as any, plot.scales)}
        {#each scaledData as d, i (i)}
            {@const borderRadius = resolveProp(args.borderRadius, d?.datum, 0) as BorderRadius}
            {@const hasBorderRadius =
                (typeof borderRadius === 'number' && borderRadius > 0) ||
                (typeof borderRadius === 'object' &&
                    Math.max(
                        borderRadius.topRight ?? 0,
                        borderRadius.bottomRight ?? 0,
                        borderRadius.topLeft ?? 0,
                        borderRadius.bottomLeft ?? 0
                    ) > 0)}
            {@const [style, styleClass] = resolveStyles(plot, d, options, 'fill', usedScales)}
            {@const { pattern, rect, path } = wafflePoly(d)}
            <g class={['waffle-x', className]}>
                <pattern {...pattern}>
                    {#if symbol}
                        {@render symbol({ ...rect, style, styleClass, datum: d.datum as Datum })}
                    {:else if hasBorderRadius}
                        <path
                            d={roundedRect(rect.x, rect.y, rect.width, rect.height, borderRadius)}
                            {style}
                            class={styleClass} />
                    {:else}
                        <rect {style} class={styleClass} {...rect} />
                    {/if}
                </pattern>
                <path {...path} />
            </g>
        {/each}
    {/snippet}
</Mark>
