<script lang="ts" generics="Datum extends DataRecord">
    interface MarkProps extends Partial<BaseMarkProps<Datum>> {
        data?: Datum[];
        automatic?: boolean;
        type: MarkType;
        channels?: ScaledChannelName[];
        required?: ScaledChannelName[];
        requiredScales?: Partial<Record<ScaleName, ScaleType[]>>;
        children?: Snippet<
            [
                {
                    mark: {
                        id: symbol;
                        type: MarkType;
                        channels: ScaledChannelName[];
                        scales: Set<ScaleName>;
                        data: DataRecord[];
                        options: GenericMarkOptions;
                    };
                    usedScales: ReturnType<typeof getUsedScales>;
                    scaledData: ScaledDataRecord<Datum>[];
                }
            ]
        >;
        defaults?: Partial<Record<ScaledChannelName, RawValue>>;
    }

    import { getContext, untrack, type Snippet } from 'svelte';
    import { CHANNEL_SCALE, INDEX } from './constants.js';
    import type {
        ScaledChannelName,
        MarkType,
        DataRecord,
        PlotContext,
        ChannelName,
        GenericMarkOptions,
        ChannelAccessor,
        BaseMarkProps,
        FacetContext,
        ScaleName,
        RawValue,
        ResolvedDataRecord,
        ScaledDataRecord,
        ScaleType
    } from './types/index.js';
    import { isEqual } from 'es-toolkit';
    import { getUsedScales, projectXY, projectX, projectY } from './helpers/scales.js';
    import { testFilter, isValid } from './helpers/index.js';
    import { resolveChannel, resolveProp } from './helpers/resolve.js';
    import { RENAME } from './transforms/rename.js';
    import { dodgeX, dodgeY } from './transforms/dodge.js';

    let {
        data = [],
        children,
        type,
        channels = [],
        required = [],
        requiredScales = {},
        defaults = {},
        ...options
    }: MarkProps = $props();

    const channelsWithFacets: ScaledChannelName[] = $derived([...channels, 'fx', 'fy']);

    const { addMark, removeMark, getTopLevelFacet, getPlotState } =
        getContext<PlotContext>('svelteplot');

    const plot = $derived(getPlotState());
    const facet = $derived(getTopLevelFacet());

    const { getFacetState } = getContext<FacetContext>('svelteplot/facet');
    const { left, top } = $derived(getFacetState());

    class Mark {
        id;
        type;
        channels: ScaledChannelName[] = $state.raw([]);
        scales: Set<ScaleName> = $state.raw(new Set());
        data: DataRecord[] = $state.raw([]);
        options: GenericMarkOptions = $state.raw({});

        constructor(type: MarkType) {
            this.id = Symbol();
            this.type = type;
        }
    }

    const mark = new Mark(type);

    $effect(() => {
        return () => {
            removeMark(mark);
            added = false;
        };
    });

    // let mark2 = $state(mark);
    const facetMode = $derived(options.facet || 'auto');

    const optionsWithAutoFacet = $derived({
        ...options,
        __firstFacet: left && top,
        ...(facet &&
        facet.data &&
        ((facetMode === 'auto' && facet.data === data) || facetMode === 'include')
            ? {
                  fx: facet.x,
                  fy: facet.y
              }
            : {})
    });

    let added = false;

    $effect(() => {
        const prevOptions = untrack(() => mark.options);
        if (!isEqual(prevOptions, optionsWithAutoFacet)) {
            mark.options = optionsWithAutoFacet;
        }
    });

    $effect(() => {
        if (added) return;
        // without using untrack() here we end up with inexplicable
        // circular dependency updates resulting in a stack overflow
        const channels = untrack(() => channelsWithFacets);
        mark.channels = channels;
        mark.scales = new Set(
            channels
                .filter((channel) => (options as any)[channel] !== 0)
                .map((channel) => CHANNEL_SCALE[channel])
        );
        mark.data = untrack(() => data);
        mark.options = untrack(() => optionsWithAutoFacet);

        addMark(mark);
        added = true;
    });

    const { getTestFacet } = getContext<FacetContext>('svelteplot/facet');
    const testFacet = $derived(getTestFacet());

    const resolvedData: ResolvedDataRecord<Datum>[] = $derived(
        data
            .map((d, i) => ({ ...d, [INDEX]: i }))
            .flatMap((row, index) => {
                const channels = options as Record<ChannelName, ChannelAccessor<Datum>>;
                if (!testFacet(row, channels) || !testFilter(row, channels)) return [];
                const out: ResolvedDataRecord<Datum> = {
                    datum: row,
                    index
                };
                for (const [channel] of Object.entries(CHANNEL_SCALE) as [
                    ScaledChannelName,
                    ScaleName
                ][]) {
                    // check if the mark has defined an accessor for this channel
                    if ((options as any)?.[channel] !== undefined && out[channel] === undefined) {
                        // resolve value
                        out[channel] = resolveChannel(channel, row, options as any);
                        if ((options as any)[channel] === INDEX) {
                            const scale = plot.scales[CHANNEL_SCALE[channel]];
                            if (scale.type === 'band' || scale.type === 'point') {
                                out[channel] = scale.domain[out[channel] % scale.domain.length];
                            }
                        }
                    }
                }
                return [out];
            })
    );

    let prevResolvedData: ResolvedDataRecord[] = [];

    $effect(() => {
        if (
            isDifferent(
                data as unknown as ResolvedDataRecord[],
                mark.data as unknown as ResolvedDataRecord[]
            ) ||
            isDifferent(resolvedData, prevResolvedData)
        ) {
            prevResolvedData = resolvedData;
            // data has changed
            mark.data = data;
        }
    });

    function isDifferent(array1: ResolvedDataRecord[], array2: ResolvedDataRecord[]) {
        if (array1.length !== array2.length) return true;
        for (let i = 0; i < array1.length; i++) {
            for (const [channel] of Object.entries(CHANNEL_SCALE) as [
                ScaledChannelName,
                ScaleName
            ][]) {
                if (!isEqual(array1[i][channel], array2[i][channel])) {
                    return true;
                }
            }
        }
        return false;
    }

    const errors = $derived([
        ...required
            .filter((name) => (options as any)[name] == null)
            .map((name) => `missing channel value for ${mark.type} mark: ${name}`),
        ...Object.entries(requiredScales)
            .filter(([scale, types]) => {
                return !types.includes((plot.scales as any)[scale].type);
            })
            .map(
                ([scale, types]) => `scale type mismatch for ${scale} (needs ${types.join(' or ')})`
            )
    ]);

    $effect(() => {
        for (const name of required) {
            if ((options as any)[name] == null) throw new Error(`missing channel value: ${name}`);
        }
    });

    const usedScales = $derived(getUsedScales(plot, optionsWithAutoFacet, mark));
    /**
     * based on the data and the global scales we can now map the data
     * elements to the scales
     */
    const scaledData = $derived(
        dodge(
            resolvedData.flatMap((row) => {
                const out: ScaledDataRecord<Datum> = {
                    datum: row.datum,
                    resolved: row,
                    index: (row as any)[INDEX],
                    valid: true,
                    dx: 0,
                    dy: 0
                };
                // compute dx/dy
                out.dx = Number(resolveProp<number, Datum>(options.dx, out.datum, 0));
                out.dy = Number(resolveProp<number, Datum>(options.dy, out.datum, 0));

                // special handling if there's a projection, e.g. a line mark
                if (plot.scales.projection && mark.type !== 'geo') {
                    for (const suffix of ['', '1', '2']) {
                        if (
                            (options as any)?.[`x${suffix}`] !== undefined &&
                            (options as any)?.[`y${suffix}`] !== undefined
                        ) {
                            // we have two-dimensional accessors
                            // for the x and y channels
                            const [x, y] =
                                mark.type === 'line'
                                    ? [row.x, row.y] // line paths are projected later
                                    : projectXY(
                                          plot.scales,
                                          row.x,
                                          row.y,
                                          usedScales.x,
                                          usedScales.y
                                      );

                            (out as any)[`x${suffix}`] = x;
                            (out as any)[`y${suffix}`] = y;
                            out.valid =
                                out.valid &&
                                isValid(row.x) &&
                                isValid(row.y) &&
                                isValid(x) &&
                                isValid(y);
                        }
                    }
                }

                // iterate over all scaled channels
                for (const [channel, scale] of Object.entries(CHANNEL_SCALE) as [
                    ScaledChannelName,
                    ScaleName
                ][]) {
                    // check if the mark has defined an accessor for this channel
                    if (
                        (options as any)?.[channel] != null &&
                        (out as any)[channel] === undefined
                    ) {
                        // resolve value
                        const value = row[channel];
                        // if this channel was renamed, use the original channel for scaling
                        const origChannel = (options as any)?.[RENAME]?.[channel] || channel;
                        const scaled = usedScales[channel]
                            ? scale === 'x'
                                ? projectX(origChannel as 'x' | 'x1' | 'x2', plot.scales, value)
                                : scale === 'y'
                                  ? projectY(origChannel as 'y' | 'y1' | 'y2', plot.scales, value)
                                  : scale === 'color' && !isValid(value)
                                    ? plot.options.color.unknown
                                    : plot.scales[scale].fn(value)
                            : value;

                        out.valid =
                            out.valid &&
                            (scale === 'color' ||
                                scale === 'fx' ||
                                scale === 'fy' ||
                                isValid(value));

                        // apply dx/dy transform
                        (out as any)[channel] =
                            Number.isFinite(scaled) && (scale === 'x' || scale === 'y')
                                ? scaled + (scale === 'x' ? out.dx : out.dy)
                                : scaled;
                    } else if (defaults[channel]) {
                        (out as any)[channel] = defaults[channel];
                    }
                }

                return [out];
            }),
            options
        )
    );

    function dodge<T>(data: ScaledDataRecord<Datum>[], options: BaseMarkProps<T>) {
        if (options.dodgeX) {
            return dodgeX({ data, ...options } as any, plot) as ScaledDataRecord<Datum>[];
        }
        if (options.dodgeY) {
            return dodgeY({ data, ...options } as any, plot) as ScaledDataRecord<Datum>[];
        }
        return data;
    }
</script>

{#if errors.length}
    <text transform="translate(10,10)">
        {#each errors as error, i (i)}
            <tspan x="0" dy={i ? 14 : 0}>{error}</tspan>
        {/each}
    </text>
{:else if children}
    {@render children({
        mark,
        usedScales,
        scaledData
    })}
{/if}

<style>
    text {
        stroke: var(--svp-bg);
        fill: crimson;
        font-size: 11px;
        stroke-width: 3px;
        font-weight: bold;
        paint-order: stroke fill;
    }
</style>
